/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const vm = require('vm');
const assert = require('assert/strict');
const html = fs.readFileSync('/workspace/small-hours.html', 'utf8');
const script = html.match(/<script>([\\s\\S]*?)<\\/script>/)[1];
new vm.Script(script);
const context2d = new Proxy({}, {get: (target, key) => target[key] || (key.startsWith('create') ? () => ({addColorStop() {}}) : () => {}), set: (target, key, value) => (target[key] = value, true)});
function element() {
  const listeners = {};
  return {listeners, addEventListener(name, handler) {listeners[name] = handler;}, getContext() {return context2d;}, setAttribute() {}, setPointerCapture() {}, toBlob(callback) {callback({type: 'image/png'});}, append() {}, click() {this.clicked = true;}, remove() {}};
}
const ids = Object.fromEntries(['sky', 'undo', 'clear', 'motion', 'status', 'save'].map(id => ['#' + id, element()]));
const document = {querySelector: id => ids[id], createElement: element, body: element(), addEventListener() {}, hidden: false};
const sandbox = {document, innerWidth: 1200, innerHeight: 800, devicePixelRatio: 2, matchMedia: () => ({matches: true, addEventListener() {}}), requestAnimationFrame: () => 1, cancelAnimationFrame() {}, addEventListener() {}, setTimeout() {}, URL: {createObjectURL: () => 'blob:test', revokeObjectURL() {}}};
vm.createContext(sandbox);
vm.runInContext(script, sandbox);
const inspect = expression => vm.runInContext(expression, sandbox);
assert.equal(inspect('strokes.length'), 2);
assert.equal(ids['#motion'].textContent, 'Twinkle');
assert.equal(ids['#undo'].disabled, true);
const sky = ids['#sky'];
const pointer = (x, y) => ({pointerId: 1, pointerType: 'mouse', button: 0, clientX: x, clientY: y});
sky.listeners.pointerdown(pointer(100, 400));
sky.listeners.pointermove(pointer(160, 460));
sky.listeners.pointerup(pointer(160, 460));
assert.equal(inspect('strokes.length'), 3);
assert.equal(inspect('strokes[2].length'), 2);
ids['#undo'].listeners.click();
assert.equal(inspect('strokes.length'), 2);
ids['#clear'].listeners.click();
assert.equal(inspect('strokes.length'), 0);
assert.equal(ids['#clear'].disabled, true);
ids['#undo'].listeners.click();
assert.equal(inspect('strokes.length'), 2);
const key = (key, code) => ({key, code, preventDefault() {}});
sky.listeners.keydown(key('ArrowRight', 'ArrowRight'));
sky.listeners.keydown(key(' ', 'Space'));
sky.listeners.keydown(key('ArrowDown', 'ArrowDown'));
sky.listeners.keydown(key(' ', 'Space'));
assert.equal(inspect('strokes[2].length'), 2);
ids['#undo'].listeners.click();
assert.equal(inspect('strokes[2].length'), 1);
const beforeResize = inspect('JSON.stringify(strokes)');
sandbox.innerWidth = 400; sandbox.innerHeight = 700;
inspect('resize()');
assert.equal(inspect('JSON.stringify(strokes)'), beforeResize);
ids['#save'].listeners.click();
assert.equal(ids['#status'].textContent, 'Your sky is ready as small-hours.png.');
ids['#motion'].listeners.click();
assert.equal(ids['#motion'].textContent, 'Pause');
console.log('Passed: JavaScript syntax, drawing, undo, reversible clear, keyboard input, responsive coordinates, PNG export callback, and motion controls.');
console.log('Browser rendering was not exercised; no browser runtime is installed.');
NODE"

